func (m *CameraRequestsRepositoryMock) MinimockVoteCameraRequestDone() bool {
	if m.VoteCameraRequestMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.VoteCameraRequestMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.VoteCameraRequestMock.invocationsDone()
}

// MinimockVoteCameraRequestInspect logs each unmet expectation
func (m *CameraRequestsRepositoryMock) MinimockVoteCameraRequestInspect() {
	for _, e := range m.VoteCameraRequestMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to CameraRequestsRepositoryMock.VoteCameraRequest at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterVoteCameraRequestCounter := mm_atomic.LoadUint64(&m.afterVoteCameraRequestCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.VoteCameraRequestMock.defaultExpectation != nil && afterVoteCameraRequestCounter < 1 {
		if m.VoteCameraRequestMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to CameraRequestsRepositoryMock.VoteCameraRequest at\n%s", m.VoteCameraRequestMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to CameraRequestsRepositoryMock.VoteCameraRequest at\n%s with params: %#v", m.VoteCameraRequestMock.defaultExpectation.expectationOrigins.origin, *m.VoteCameraRequestMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcVoteCameraRequest != nil && afterVoteCameraRequestCounter < 1 {
		m.t.Errorf("Expected call to CameraRequestsRepositoryMock.VoteCameraRequest at\n%s", m.funcVoteCameraRequestOrigin)
	}

	if !m.VoteCameraRequestMock.invocationsDone() && afterVoteCameraRequestCounter > 0 {
		m.t.Errorf("Expected %d calls to CameraRequestsRepositoryMock.VoteCameraRequest at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.VoteCameraRequestMock.expectedInvocations), m.VoteCameraRequestMock.expectedInvocationsOrigin, afterVoteCameraRequestCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *CameraRequestsRepositoryMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockCreateCameraRequestInspect()

			m.MinimockListCameraRequestsInspect()

			m.MinimockSetCameraRequestStatusInspect()

			m.MinimockVoteCameraRequestInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *CameraRequestsRepositoryMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *CameraRequestsRepositoryMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockCreateCameraRequestDone() &&
		m.MinimockListCameraRequestsDone() &&
		m.MinimockSetCameraRequestStatusDone() &&
		m.MinimockVoteCameraRequestDone()
}
